function process(items) {
  const sorted = [...items].sort((a, b) => a.ts - b.ts);
  const index = new Map(sorted.map(i => [i.id, i]));
  let merged = 0;
  for (const item of sorted) {
    if (index.has(item.parentId)) merged++;
  }
  return { sorted, merged };
}

